begin;
create function pg_temp.ok(value boolean,message text) returns void language plpgsql as $$ begin if value is distinct from true then raise exception 'FAIL: %',message; end if; end $$;
create function pg_temp.denied(statement text) returns void language plpgsql as $$ declare blocked boolean:=false; begin begin execute statement; exception when others then blocked:=true; end; if not blocked then raise exception 'FAIL: allowed %',statement; end if; end $$;
create function pg_temp.act(title text,action text,note text default '') returns void language sql as $$ select public.club_governance(jsonb_build_object('request_id',(select id from public.club_requests where club_requests.title=$1),'action',$2,'note',$3)) $$;
